/** Engine-level campaign traversal. No fabricated quest flags, levels, AP, victories or save states. */
import fs from 'node:fs';import assert from 'node:assert/strict';
import {World} from '../world.js?v=5.41';import{choiceCondition}from '../campaign-content.js';import{Battle,encounterEnemies}from '../battle.js?v=5.38';import{compileTechnique}from '../mako.js';import{findPath}from '../navigation.js';
const source=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url)));let data;
const branch=Number(process.argv[2]||0);let dialog,select=0,steps=0,fights=0,moves=0,visited=new Set();
const w=new World(source,{onDialog:d=>dialog=d,onBattle:fight});data=w.data;
function drain(){for(let i=0;dialog&&i<80;i++){const d=dialog;dialog=null;if(d.choices){const n=Math.min(select,d.choices.length-1);select=0;d.choices[n].action();}else d.after?.();}assert.ok(!dialog,'dialog cycle');}
function fight(origin){const s=w.state,hs=w.activeHeroes;hs.forEach((h,i)=>{h.x=s.x+(i===1?-.9:i===2?.9:0);h.y=s.y+(i?.7:0);});const xy=origin.object.xy||origin.object.enemies[0][1],es=encounterEnemies(origin.mission.id,origin.object.type==='boss',origin.object.enemies?.length||2);es.forEach((e,i)=>{e.x=xy[0]+.5+(i%2)*1.3;e.y=xy[1]+.5+Math.floor(i/2)*1.4;});const b=new Battle({heroes:hs,enemies:es,chapter:origin.mission.id,rng:()=>.5});
 for(let tick=0;tick<30000&&!b.ended;tick++){b.advance(.1);for(const h of [...b.ready]){const low=hs.filter(a=>a.hp>0).sort((a,c)=>a.hp/a.maxHp-c.hp/c.maxHp)[0],dead=hs.find(a=>a.hp<=0);if(dead&&s.items.revive){s.items.revive--;dead.hp=Math.round(dead.maxHp*.4);h.atb=0;continue;}const heal=h.loadout.find(x=>x.core==='mend');if(low.hp<low.maxHp*.65&&heal){b.command(h.id,'tech',low.id,compileTechnique(heal.core,heal.support,{character:h.id,ap:h.ap[heal.core]||0}));continue;}if(low.hp<low.maxHp*.45&&s.items.tonic){s.items.tonic--;low.hp=Math.min(low.maxHp,low.hp+Math.max(100,low.maxHp*.45));h.atb=0;continue;}if(h.mp<8||h.strain>70){b.command(h.id,'guard',h.id);continue;}const slot=h.loadout.find(x=>x.core==='earth')||h.loadout.find(x=>!['mend','ward','revive'].includes(x.core));if(slot)b.command(h.id,'tech',b.livingEnemies[0]?.id,compileTechnique(slot.core,slot.support,{character:h.id,ap:h.ap[slot.core]||0}));else b.command(h.id,'attack',b.livingEnemies[0]?.id);}}
 assert.equal(b.ended,'win',`battle chapter ${origin.mission.id}, ${origin.object.type}`);fights++;w.winBattle();}
function walk(p,radius=1){const path=findPath(w.scene,[w.state.x,w.state.y],p,radius);for(const [x,y]of path){for(let i=0;i<20&&Math.hypot(w.state.x-x,w.state.y-y)>.02;i++){const dx=x-w.state.x,dy=y-w.state.y,d=Math.hypot(dx,dy);w.move(dx/d*Math.min(.2,d),dy/d*Math.min(.2,d));moves++;}}assert.ok(Math.hypot(w.state.x-p[0]-.5,w.state.y-p[1]-.5)<2.05,`unreachable ${w.scene.key}:${p}`);}
function target(r,o){if(o.to==='hub')return w.scenes.get(226);if(o.to_region){const m=data.campaign.missions[o.to_region-1];return data.scenes.find(v=>v.chapter===o.to_region&&v.key===(o.to_room||o.to))||data.scenes.find(v=>v.location===m.rooms[0].location);}return data.scenes.find(v=>v.chapter===r.chapter&&v.key===o.to)||data.scenes.find(v=>v.key===o.to);}
function ready(o){return (o.requires_flags||[]).every(p=>w.bit(...p))&&(o.requires===undefined||w.bit(w.flagFor(o),o.requires));}
function go(room){if(w.scene.location===room.location)return true;const queue=[{r:w.scene,path:[]}],seen=new Set([w.scene.location]);for(let i=0;i<queue.length;i++){const{r,path}=queue[i];for(const o of [...r.objects.filter(o=>o.type==='portal'),...r.doors]){if(!ready(o)||o.to_region>w.state.chapter)continue;const available=![o.appears_when,o.disabled_by].some(p=>p&&choiceCondition(w,p)?.known===false)&&(!o.disabled_by||!w.bit(...o.disabled_by))&&(!o.appears_when||w.bit(...o.appears_when));if(!available)continue;const t=target(r,o);if(!t||(t.access_requires||[]).some(p=>!w.bit(...p))||seen.has(t.location))continue;const p=[...path,o];if(t.location===room.location){for(const door of p){walk(door.xy);w.portal(door);drain();visited.add(w.scene.location);}assert.equal(w.scene.location,room.location);return true;}seen.add(t.location);queue.push({r:t,path:p});}}return false;}
function act(o){walk(o.xy||o.enemies[0][1]);select=o.type==='puzzle'?o.choice_effects?(o.choice_id?branch:0):o.steps[o.stage_flag&&w.bit(...o.stage_flag)?1:0].answer:0;if(o.type==='project'&&w.state.gold<300)select=1;w.interact(o);steps++;drain();}
drain();visited.add(w.scene.location);
// Earn the opening with walked, ordinary interactions before traversing the campaign.
act(w.objects().find(o=>o.type==='npc'));act(w.objects().find(o=>o.type==='portal'));act(w.objects().find(o=>o.type==='puzzle'&&o.bit===0));act(w.objects().find(o=>o.type==='puzzle'&&o.bit===1));act(w.objects().find(o=>o.type==='portal'&&o.to==='workshop'));act(w.objects().find(o=>o.type==='cache'&&o.bit===1));act(w.objects().find(o=>o.type==='puzzle'&&o.bit===3));act(w.objects().find(o=>o.type==='portal'&&o.to==='security'));act(w.objects().find(o=>o.storyEvent==='iona'));

for(let chapter=1;chapter<=24;chapter++){
 const rooms=data.scenes.filter(r=>r.chapter===chapter);let done=false;
 for(let pass=0;pass<12&&!done;pass++){
  let changes=0;
  for(const r of rooms){if(!go(r))continue;visited.add(r.location);for(const type of ['cache','npc','patrol','aid','switch','note','puzzle','project'])for(const o of r.objects.filter(o=>o.type===type)){if(w.scene.location!==r.location&&!go(r))continue;if(!w.available(o)||!ready(o))continue;if(type==='npc'&&(o.sets_bit===undefined||w.bit(w.flagFor(o),o.sets_bit)))continue;if(['cache','patrol','aid','switch','puzzle','project'].includes(type)&&w.done(o))continue;if(type==='note'){if(w.bit(w.flagFor(o),o.completes_bit))continue;const at=w.state.flags['sequence:'+o.sequence_address]||0;if(o.pattern[at]!==o.note)continue;}const before=w.save();act(o);changes+=before!==w.save();}
  }
  for(const r of rooms){const boss=r.objects.find(o=>o.type==='boss');if(!boss||!go(r)||!ready(boss))continue;const camp=r.objects.find(o=>o.type==='camp');if(camp)act(camp);act(boss);done=w.state.bosses.includes(chapter);if(done)break;}
  if(!changes&&!done)throw Error(`stalled chapter ${chapter}: ${w.objectiveText()}`);
 }
 assert.ok(done,'completed '+chapter);console.log(JSON.stringify({chapter,level:w.activeHeroes[0].level,fights,rooms:visited.size,steps,moves}));
 const saved=w.save();w.restore(saved);assert.equal(w.state.chapter,chapter+1);
}
assert.equal(w.state.complete,true);assert.equal(Object.keys(w.state.storyChoices).filter(k=>w.state.storyChoices[k]!==null).length,7);console.log(JSON.stringify({result:'pass',scope:'engine-level actions, not browser/controller proof',branch,fights,rooms:visited.size,steps,moves,choices:w.state.storyChoices}));
